app.get('/api/icu/patients/:patientId/telemetry', checkAuth, async (req, res) => {
  const assignment = await IcuAssignment.findOne({
    where: { patientId: req.params.patientId, staffId: req.user.id, active: true }
  });
  if (!assignment) {
    return res.status(403).send('Forbidden: clinician not assigned to patient in ICU');
  }

  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    Connection: 'keep-alive'
  });

  const sendVitals = (data) => {
    res.write(`data: ${JSON.stringify(data)}\n\n`);
  };

  telemetryBus.on(`patient:${req.params.patientId}`, sendVitals);
  req.on('close', () => {
    telemetryBus.off(`patient:${req.params.patientId}`, sendVitals);
  });
});
